def smallest_difference(array1, array2):
    array1.sort()
    array2.sort()

    smallest_diff = float('inf')
    idx1, idx2 = 0, 0
    result = None
    while idx1 < len(array1) and idx2 < len(array2):
        diff = abs(array1[idx1] - array2[idx2])
        if diff == 0:
            return (array1[idx1], array2[idx2])
        elif diff < smallest_diff:
            smallest_diff = diff
            result = (array1[idx1], array2[idx2])
        if array1[idx1] < array2[idx2]:
            idx1 += 1
        else:
            idx2 += 1
    return result

